import { BQ79616PAPRQ1 } from "./imports/BQ79616PAPRQ1"
import { DZT5401_13 } from "./imports/DZT5401_13"

export const BmsMonitorModule = () => {
  return (
    <group name="bms-monitor-module">
      {/* Main IC */}
      <BQ79616PAPRQ1 name="U1" />

      {/* External NPN for LDOIN Regulation */}
      <DZT5401_13 name="Q1" />

      {/* Connectivity between U1 and Q1 */}
      <net name="BAT" connections={["U1.BAT", "Q1.C1", "Q1.C2", "J_CELL.pin18"]} />
      <net name="LDOIN" connections={["U1.LDOIN", "Q1.E"]} />
      <net name="NPNB" connections={["U1.NPNB", "Q1.B"]} />

      {/* Bypass Capacitors for Regulators */}
      <capacitor name="C_LDOIN" value="0.1uF" footprint="0603" connections={["LDOIN", "CVSS"]} />
      <capacitor name="C_AVDD" value="1uF" footprint="0603" connections={["U1.AVDD", "AVSS"]} />
      <capacitor name="C_DVDD" value="1uF" footprint="0603" connections={["U1.DVDD", "DVSS"]} />
      <capacitor name="C_CVDD" value="4.7uF" footprint="0603" connections={["U1.CVDD", "CVSS"]} />

      {/* Cell Inputs and Balancing */}
      {Array.from({ length: 17 }).map((_, i) => (
        <group key={`cell_tap_${i}`}>
          <resistor
            name={`R_VC${i}`}
            value="100"
            footprint="0603"
            connections={[`VC_NODE_${i}`, `U1.VC${i}`]}
          />
          {/* Fuses are required on each sense tap */}
          <resistor
            name={`F${i}`}
            value="0.1"
            footprint="0603"
            connections={[`J_CELL.pin${i + 1}`, `VC_NODE_${i}`]}
          />
        </group>
      ))}

      {/* Differential Filter Capacitors */}
      {Array.from({ length: 16 }).map((_, i) => (
        <capacitor
          key={`C_VC_DIFF_${i + 1}`}
          name={`C_VC${i + 1}`}
          value="0.1uF"
          footprint="0603"
          connections={[`U1.VC${i + 1}`, `U1.VC${i}`]}
        />
      ))}

      {/* Balancing Resistors */}
      {Array.from({ length: 16 }).map((_, i) => (
        <resistor
          key={`R_CB${i}`}
          name={`R_CB${i}`}
          value="22"
          footprint="1210"
          connections={[`VC_NODE_${i + 1}`, `U1.CB${i}`]}
        />
      ))}

      {/* Isolated Daisy Chain */}
      <group name="COMM_ISO">
        <capacitor name="C_ISO1" value="4.7nF" footprint="1206" connections={["U1.COMHP", "J_COMM_H.pin1"]} />
        <capacitor name="C_ISO2" value="4.7nF" footprint="1206" connections={["U1.COMHN", "J_COMM_H.pin2"]} />
        <capacitor name="C_ISO3" value="4.7nF" footprint="1206" connections={["U1.COMLP", "J_COMM_L.pin1"]} />
        <capacitor name="C_ISO4" value="4.7nF" footprint="1206" connections={["U1.COMLN", "J_COMM_L.pin2"]} />
      </group>

      {/* NTC Thermistor Pull-ups */}
      {Array.from({ length: 8 }).map((_, i) => (
        <resistor
          key={`R_NTC_PU${i + 1}`}
          name={`R_NTC${i + 1}`}
          value="10k"
          footprint="0603"
          connections={["U1.TSREF", `U1.GPIO${i + 1}`]}
        />
      ))}

      {/* Common Grounds */}
      <net name="AVSS" connections={["U1.AVSS", "U1.VC0", "VC_NODE_0"]} />
      <net name="CVSS" connections={["U1.CVSS", "AVSS"]} />
      <net name="DVSS" connections={["U1.DVSS", "AVSS"]} />

      {/* Connectors (Abstracted) */}
      <chip name="J_CELL" pinLabels={{ pin1: "VC0", pin17: "VC16", pin18: "BAT" }} />
      <chip name="J_COMM_H" pinLabels={{ pin1: "HP", pin2: "HN" }} />
      <chip name="J_COMM_L" pinLabels={{ pin1: "LP", pin2: "LN" }} />
    </group>
  )
}

